const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Point near the coast of La Jolla, California
  const point = ee.Geometry.Point([-117.27, 32.84]);
  // A small buffer to sample the coastal area
  const areaOfInterest = point.buffer(1000); // 1km buffer
  const dateStart = '2018-08-01';
  const dateEnd = '2018-08-02';

  // 2. Data Acquisition & Check
  // NOAA CDR SST Pathfinder V5.3 is a daily product.
  let sstCollection = ee.ImageCollection('NOAA/CDR/SST_PATHFINDER/V53')
    .filterDate(dateStart, dateEnd)
    .filterBounds(areaOfInterest);

  let collectionSize = sstCollection.size().getInfo();
  if (collectionSize === 0) {
    console.log('No NOAA/CDR/SST_PATHFINDER images found for the specified date and location.');
    // Fallback: Try JPL MURSST, which is also a daily high-res product
    sstCollection = ee.ImageCollection('JPL/MURSST41')
        .filterDate(dateStart, dateEnd)
        .filterBounds(areaOfInterest);
    collectionSize = sstCollection.size().getInfo();
    if (collectionSize === 0) {
        console.log('Fallback to JPL/MURSST41 also found no images.');
        console.log('C1: Empty Collection');
        return;
    }
  }

  // 3. Processing
  // Create a composite image for the day
  const sstImage = sstCollection.mean();

  // The 'sea_surface_temperature' band is in Kelvin with a scale factor of 0.01.
  // GEE handles the scale factor. We just convert from Kelvin to Celsius.
  const sstCelsius = sstImage.select('sea_surface_temperature').subtract(273.15);

  // Check for valid pixels in the region.
  const pixelCount = sstCelsius.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: areaOfInterest,
    scale: 1000,
    maxPixels: 1e9
  }).get('sea_surface_temperature').getInfo();

  if (pixelCount === 0 || pixelCount === null) {
    console.log(`Image collection size: ${collectionSize}`);
    console.log('No valid SST pixels found in the area of interest after processing.');
    console.log('C2: No Valid Pixels');
    return;
  }

  // 4. Calculation
  // Calculate the mean temperature in the area.
  const meanTemp = sstCelsius.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: areaOfInterest,
    scale: 1000,
    maxPixels: 1e9
  }).get('sea_surface_temperature');

  const meanTempInfo = meanTemp.getInfo();

  // 5. Validation & Final Answer
  if (meanTempInfo === null) {
    console.log(`Image collection size: ${collectionSize}`);
    console.log(`Valid pixels found: ${pixelCount}`);
    console.log('Calculation resulted in null. This might be due to masked pixels.');
    console.log('C3: Calculation Failure');
    return;
  }

  const tempThreshold = 23; // degrees Celsius
  const tempExceeded = meanTempInfo > tempThreshold;

  console.log(`Date: ${dateStart}`);
  console.log(`Location: La Jolla, CA (Lat: 32.84, Lon: -117.27)`);
  console.log(`Valid SST Pixels: ${pixelCount}`);
  console.log(`Mean Sea Surface Temp: ${meanTempInfo.toFixed(2)} C`);
  console.log(`Did temperature exceed ${tempThreshold} C? ${tempExceeded ? 'Yes' : 'No'}`);

  if (tempExceeded) {
    console.log('A: Yes');
  } else {
    console.log('B: No');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, () => resolve(), reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, () => resolve(), reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log('D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.');
});
